<?php
declare(strict_types=1);
namespace App\Extensions\TitanMapsIntelligence\Tools;
use App\Extensions\TitanMapsIntelligence\Contracts\AuthorisedCompanyContext;use App\Extensions\TitanMapsIntelligence\Contracts\PermissionAuthorizer;use App\Extensions\TitanMapsIntelligence\Exceptions\MapsIntelligenceException;use App\Extensions\TitanMapsIntelligence\Services\DispatchScoringPolicyService;use App\Extensions\TitanMapsIntelligence\Services\GovernedSpatialCapabilityExecutor;
final class UpdateDispatchWeightsTool { public function __construct(private readonly AuthorisedCompanyContext $context,private readonly PermissionAuthorizer $auth,private readonly DispatchScoringPolicyService $policies,private readonly GovernedSpatialCapabilityExecutor $governance){} public function execute(array $input):array{if(($input['confirmed']??false)!==true)throw MapsIntelligenceException::fromCode('MAPS_CONFIRMATION_REQUIRED','Dispatch scoring policy update requires confirmation.');$this->auth->authorize($this->context->userId(),$this->context->companyId(),'titan-maps-intelligence.dispatch.weights.update');$input['execution_origin']='ai';return $this->governance->execute('maps.dispatch.weights.update',$input,function()use($input){$p=$this->policies->update((array)$input['weights'],isset($input['vertical'])?(string)$input['vertical']:null,(string)($input['policy_version']??'tenant-v1'));return ['policy_id'=>(string)$p->id,'vertical'=>$p->vertical,'policy_version'=>$p->policy_version,'weights'=>$p->weights];});}}
